let organizationAuthStep=0,organizationSignupDraft={};
function hiringPreferences(){return {...(organizationUser()?.user_metadata?.organization_setup||{})}}
function orgInput(name,label,value='',type='text',required=true,placeholder=''){return '<label class="field">'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(type==='password'?'':value||'')+'" '+(required?'required':'')+' '+(type==='password'?'minlength="8" maxlength="128" autocomplete="'+(location.hash==='#organization-login'?'current-password':'new-password')+'"':'maxlength="'+(['name','full_name','organization_name'].includes(name)?120:250)+'"')+' placeholder="'+esc(placeholder)+'"></label>'}
function orgSelect(name,label,options,value=''){return '<label class="field">'+label+'<select name="'+name+'" required><option value="">Choose an option</option>'+options.map(o=>'<option '+(value===o?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></label>'}
function organizationAuthPage(){const signup=location.hash==='#organization-signup',d=organizationSignupDraft;sessionStorage.setItem('nextwork-auth-intent','organization');return '<div class="employer-access"><section class="employer-story"><a class="landing-brand" href="#home"><img src="assets/brand/nextwork-icon.png" alt="">nextwork</a><span class="employer-eyebrow">FOR ORGANIZATIONS</span><h1>Your next great hire starts with meaningful work.</h1><p>Bring graduates into real projects with clear outcomes, then review every application in one place.</p><div class="employer-story-step">'+icon('briefcase',22)+'<div><b>Define the work</b><small>Jobs, contracts, budgets, and deliverables.</small></div></div><div class="employer-story-step">'+icon('user',22)+'<div><b>See the person behind the application</b><small>Profiles, resume snapshots, and relevant skills.</small></div></div><div class="employer-story-step">'+icon('message',22)+'<div><b>Keep hiring moving</b><small>Shortlist, message, accept, or decline.</small></div></div><a class="employer-graduate-link" href="#login">Looking for work instead? Graduate login →</a></section><section class="employer-auth-card"><nav class="employer-auth-tabs"><a href="#organization-login" '+(!signup?'aria-current="page"':'')+'>Organization login</a><a href="#organization-signup" '+(signup?'aria-current="page"':'')+'>Create organization</a></nav>'+(organizationUser()?'<h2>You’re already signed in.</h2><p>'+esc(organizationUser().email||'Your account')+'</p><a class="primary" href="#organization">Continue to your hiring portal →</a>':'<div class="eyebrow">HIRING WORKSPACE</div><h2>'+(signup?'Tell us about your team.':'Welcome back, hiring team.')+'</h2><p>'+(signup?'Set up your account and hiring preferences. These help prepare a focused listing.':'Sign in to manage listings, review applicants, and contact candidates.')+'</p>'+(signup?'<div class="employer-form-steps"><span class="'+(organizationAuthStep===0?'active':'')+'">1. Account & company</span><span class="'+(organizationAuthStep===1?'active':'')+'">2. Hiring plans</span></div>':'')+(!signup?linkedinButton('Log in with LinkedIn','oauth')+'<div class="auth-divider"><span>or use work email</span></div>':'')+'<form id="organization-auth-form">'+(signup?(organizationAuthStep===0?'<div class="profile-fields">'+orgInput('full_name','Your name',d.full_name)+orgInput('organization_name','Organization name',d.organization_name)+orgInput('email','Work email',d.email,'email')+orgInput('password','Create password','','password')+orgInput('website','Organization website',d.website,'url',false,'https://...')+orgSelect('industry','Industry',['Software & technology','Climate & sustainability','Health & wellbeing','Finance','Education','Consumer products','Community & nonprofit','Other'],d.industry)+'</div>':'<div class="profile-fields">'+orgSelect('team_size','Team size',['Solo founder','2–10 people','11–50 people','51–200 people','201+ people'],d.team_size)+orgSelect('hiring_kind','What are you hiring for?',['Contract project','Full-time job','Part-time job'],d.hiring_kind)+orgSelect('focus_field','Primary field',Object.keys(MatchCriteria.fieldSkills),d.focus_field)+orgInput('budget','Starting compensation / project budget (USD)',d.budget,'number',true,'e.g. 1500')+orgSelect('start_window','When do you want to start?',['As soon as possible','Within 2 weeks','Within a month','Planning ahead'],d.start_window)+orgSelect('work_style','Work style',['Remote','Hybrid','On-site','Flexible'],d.work_style)+orgInput('location','Hiring location / time zone',d.location,'text',false,'e.g. Austin · Central Time')+'</div><p class="resume-hint">You can adjust compensation, scope, and location for every listing. Hiring preferences are private to your account.</p>'):orgInput('email','Work email','','email')+orgInput('password','Password','','password')+'<a class="quiet-link" href="#forgot">Forgot password?</a>')+'<div class="dialog-actions">'+(signup&&organizationAuthStep===1?'<button class="outline" type="button" onclick="organizationAuthStep=0;render()">← Back</button>':'')+'<button class="primary" type="submit" id="organization-auth-submit">'+(signup?(organizationAuthStep===0?'Continue to hiring plans →':'Create organization account →'):'Log in to hiring portal →')+'</button></div></form>'+accountFeedback()+'<p class="employer-auth-note">Already have a Nextwork graduate account? Use the same email and password here to add an organization workspace.</p>')+'</section></div>'}
function bindOrganizationAuth(){const form=$('#organization-auth-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(location.hash==='#organization-signup'&&organizationAuthStep===0){organizationSignupDraft={...organizationSignupDraft,...values};organizationAuthStep=1;render();return}return runAuth(async()=>{const button=$('#organization-auth-submit');button.disabled=true;try{sessionStorage.setItem('nextwork-auth-intent','organization');if(location.hash==='#organization-signup'){const draft={...organizationSignupDraft,...values};if(!draft.email||!draft.password||!draft.organization_name)throw Error('Return to Account & company to complete your details.');const budget=Number(draft.budget);if(!Number.isSafeInteger(budget)||budget<1||budget>2147483647)throw Error('Enter a positive budget in whole USD.');if(draft.organization_name.trim().length<2)throw Error('Enter your organization name.');const setup={organization_name:draft.organization_name.trim(),website:draft.website||'',industry:draft.industry,team_size:draft.team_size,hiring_kind:draft.hiring_kind,focus_field:draft.focus_field,budget,start_window:draft.start_window,work_style:draft.work_style,location:draft.location||''};const data=checkAuthResult(await Account.client.auth.signUp({email:draft.email.trim(),password:draft.password,options:{emailRedirectTo:authCallback(),data:{full_name:draft.full_name,account_kind:'organization',organization_setup:setup}}}));organizationSignupDraft={};organizationAuthStep=0;if(data.session){Account.user=data.session.user;location.hash=postLoginRoute()}else{Account.message='Account created. Check your work email to confirm it, then use Organization login.';location.hash='organization-login';render()}}else{const data=checkAuthResult(await Account.client.auth.signInWithPassword({email:values.email.trim(),password:values.password}));Account.user=data.user;location.hash=postLoginRoute()}}finally{button.disabled=false}})}}
function organizationOverview(){const p=Organization.profile,prefs=hiringPreferences(),listings=Organization.listings,apps=Organization.applications,live=listings.filter(l=>l.status==='published'),pending=apps.filter(a=>a.status==='submitted'),steps=[['profile','Set up your organization',Boolean(p?.name&&p?.description),'Add your public story, website, and contact details.'],['listings','Create a focused listing',listings.length>0,'Include compensation, scope, skills, and clear requirements.'],['listings','Publish your opportunity',live.length>0,'Drafts stay private until you publish them.'],['applicants','Review your first applicants',apps.length>0,'Read the person’s introduction, profile, and resume.']];return '<div class="org-overview-hero"><div><span class="eyebrow">YOUR HIRING WORKSPACE</span><h2>'+esc(p.name)+'</h2><p>'+esc(p.description||'Tell candidates what your team is building and why their work will matter.')+'</p><div class="tags">'+[prefs.industry,prefs.team_size,prefs.work_style].filter(Boolean).map(v=>'<span class="tag">'+esc(v)+'</span>').join('')+'</div></div><div><button class="primary" onclick="startOrganizationListing()">+ Create a listing</button><button class="outline" onclick="Organization.tab=\'profile\';render()">Edit organization</button></div></div><div class="org-metrics"><div><b>'+live.length+'</b><span>Published opportunities</span></div><div><b>'+pending.length+'</b><span>Applicants awaiting review</span></div><div><b>'+apps.filter(a=>a.status==='shortlisted').length+'</b><span>Shortlisted applicants</span></div></div>'+organizationPreferenceSummary()+'<div class="organization-overview-grid"><section class="panel wide-panel"><h2>Your next hiring steps</h2>'+steps.map(([tab,label,done,description])=>'<button class="org-setup-step" onclick="Organization.tab=\''+tab+'\';render()"><span class="'+(done?'done':'')+'">'+icon(done?'check':'arrow',17)+'</span><div><b>'+label+'</b><p>'+description+'</p></div><small>'+(done?'Done':'Next')+'</small></button>').join('')+'</section><section class="panel wide-panel"><h2>Recent applications</h2>'+apps.slice(0,4).map(a=>'<button class="recent-applicant" onclick="Organization.tab=\'applicants\';viewOrganizationApplicant(\''+a.id+'\')"><div><b>'+esc(a.profile.name||'Applicant')+'</b><small>'+esc(a.organization_listings?.title||'Project')+'</small></div><span class="tag">'+esc(a.status)+'</span></button>').join('')+(apps.length?'':'<div class="org-empty-guide">'+icon('user',28)+'<h3>Your next teammate starts here.</h3><p>Publish a clear listing to begin receiving applications. You’ll be able to shortlist, contact, accept, or decline each applicant.</p></div>')+'</section><section class="panel wide-panel"><h2>What makes a good brief?</h2><ul class="org-guide-list"><li><b>Explain the problem.</b> Give the applicant context, users, and the desired outcome.</li><li><b>Define the deliverable.</b> State exactly what should be handed over.</li><li><b>Be clear about compensation.</b> Include the amount and whether it is a project budget or salary.</li><li><b>Keep requirements relevant.</b> Separate essential skills from things a graduate can learn.</li><li><b>Set a realistic timeline.</b> Share working arrangements and expected availability.</li></ul><button class="outline" onclick="startOrganizationListing()">Start a listing →</button></section><section class="panel wide-panel"><h2>Your review workflow</h2><div class="org-workflow"><span>Submitted</span> → <span>Shortlisted</span> → <span>Accepted / Declined</span></div><p>Open an application to review the profile, introduction, and attached resume. Contact the person through their private application conversation.</p><p>Only your organization owner account and the applicant can access those documents and messages. Draft listings stay private.</p><button class="outline" onclick="Organization.tab=\'applicants\';render()">Open applicant inbox →</button></section></div>'}
function startOrganizationListing(){const p=hiringPreferences();Organization.tab='listings';Organization.edit={kind:p.hiring_kind||'Contract project',field:p.focus_field||'Development',budget:p.budget||'',location:p.location||p.work_style||'Remote',duration:p.hiring_kind==='Full-time job'?'Annual salary':'',skills:[]};render()}
function organizationDetailsForm(){const p=Organization.profile||{},prefs=hiringPreferences();return '<section class="panel wide-panel org-form"><div class="eyebrow">ORGANIZATION SETUP</div><h2>'+(p.id?'Your company & hiring plans':'Tell applicants who you are')+'</h2><form id="organization-profile"><h3>Your public organization profile</h3><div class="profile-fields">'+orgInput('name','Organization name',p.name||prefs.organization_name)+orgInput('website','Website',p.website||prefs.website,'url',false)+orgInput('contact_email','Public business email (optional)',p.contact_email,'email',false)+'</div><label class="field">What does your organization do?<textarea name="description" maxlength="5000" required placeholder="What are you building? Who do you help? Why does this work matter?">'+esc(p.description||'')+'</textarea></label><p class="resume-hint">Your public profile and optional business email are visible to candidates. Hiring preferences below are private account settings.</p><h3>Your hiring preferences</h3><div class="profile-fields">'+orgSelect('industry','Industry',['Software & technology','Climate & sustainability','Health & wellbeing','Finance','Education','Consumer products','Community & nonprofit','Other'],prefs.industry)+orgSelect('team_size','Team size',['Solo founder','2–10 people','11–50 people','51–200 people','201+ people'],prefs.team_size)+orgInput('contact_role','Your role on the team',prefs.contact_role,'text',false,'e.g. Founder, hiring lead')+orgSelect('hiring_kind','Default hiring type',['Contract project','Full-time job','Part-time job'],prefs.hiring_kind)+orgSelect('focus_field','Primary hiring field',Object.keys(MatchCriteria.fieldSkills),prefs.focus_field)+orgInput('budget','Default compensation / budget (USD)',prefs.budget,'number',false)+orgSelect('start_window','Expected start window',['As soon as possible','Within 2 weeks','Within a month','Planning ahead'],prefs.start_window)+orgSelect('work_style','Default work arrangement',['Remote','Hybrid','On-site','Flexible'],prefs.work_style)+orgInput('location','Hiring location / time zone',prefs.location,'text',false)+'</div><button class="primary">Save company & hiring preferences →</button><p class="review-error" id="organization-form-error" role="alert"></p></form></section>'}
function organizationPreferenceSummary(){const p=hiringPreferences();return '<div class="org-preference-summary">'+[['industry','Industry'],['team_size','Team size'],['focus_field','Hiring field'],['start_window','Start window']].map(([key,label])=>'<button onclick="editOrganizationPreferences()"><small>'+label+'</small><b>'+esc(p[key]||'Add '+label.toLowerCase())+'</b></button>').join('')+'</div>'}
function editOrganizationPreferences(){Organization.tab='profile';render()}
function clearOrganizationSignupDraft(){organizationSignupDraft={};organizationAuthStep=0}
